def solve_final():
    solutions = []
    for a in range(1, 11):
        # a^3 b^3 - 4024 <= 34689 b^1.5
        # b^3 - (34689/a^3) b^1.5 - 4024/a^3 <= 0
        # Let x = b^0.5, then x^6 - (34689/a^3) x^3 - 4024/a^3 <= 0
        # The root for x^3 is (34689/a^3 + sqrt((34689/a^3)^2 + 16*4024/a^3))/2
        # Actually, let's just use a safe upper bound.

        limit_b = int((38713 / (a**3))**(2/3)) + 100
        for b in range(a, limit_b):
            c_min_sq = (2012 * b) / (3 * a**2)
            f_c_min = a**3 * (c_min_sq**1.5) - 2012 * a * b * (c_min_sq**0.5) + a**3 * b**3 - 4024
            if f_c_min > 0:
                continue

            c_max = int((2012 * b / (a**2) + b**2)**0.5) + 1
            low = max(b, int(c_min_sq**0.5))
            high = c_max
            while low <= high:
                mid = (low + high) // 2
                val = a**3 * (mid**3) - 2012 * a * b * mid + a**3 * b**3 - 4024
                if val == 0:
                    solutions.append((a, b, mid))
                    break
                elif val < 0:
                    low = mid + 1
                else:
                    high = mid - 1
    return sorted(list(set(solutions)))

print(solve_final())

def solve_extra():
    solutions = []
    for a in [11, 12]:
        for b in range(a, 20):
            c_max = int((2012 * b / (a**2) + b**2)**0.5) + 1
            for c in range(b, c_max + 1):
                if a**3 * (b**3 + c**3) == 2012 * (a * b * c + 2):
                    solutions.append((a, b, c))
    return solutions

print(solve_extra())

def solve_a1_large():
    solutions = []
    for b in range(1, 2013):
        # c^3 - 2012bc + b^3 - 4024 = 0
        c_max = int((2012 * b + b**2)**0.5) + 1
        for c in range(b, c_max + 1):
            if c**3 - 2012 * b * c + b**3 - 4024 == 0:
                solutions.append((1, b, c))
                break
    return solutions

