def solve_all():
    solutions = []
    for a in range(1, 13):
        limit_b = int(2012 / (a**2)) + 1
        for b in range(a, limit_b):
            c_max = int((2012 * b / (a**2) + b**2)**0.5) + 1
            for c in range(b, c_max + 1):
                if a**3 * (b**3 + c**3) == 2012 * (a * b * c + 2):
                    solutions.append((a, b, c))
    return solutions

